// Proposals router — pure composition. Every leaf lives in its own file and
// imports its pre-scoped procedures from ./procedures. The only non-leaf entry
// is `crud` (generated by createCrudRouter) + `media` (still on the toolkit
// until S5) — both still need `entity` because createCrudRouter/media type
// their procedure params as `typeof agentProcedure`. The createEntityRouter
// wrapper is removed in S7 once those two are off the toolkit.
// see ../../DOCS.md#entity-router-via-factory (being rewritten — epic S7)

import z from 'zod'

import { duplicateProposalWithIncentives } from '@/shared/entities/proposals/dal/server/duplicate'
import { proposalSchemas, proposalServerSpec } from '@/shared/entities/proposals/lib/server-spec'

import { createTRPCRouter } from '../../init'
import { createCrudRouter } from '../../lib/create-crud-router'
import { createEntityRouter } from '../../lib/create-entity-router'
import { businessRouter } from './business.router'
import { contractsRouter } from './contracts.router'
import { deliveryRouter } from './delivery.router'
import { fundingRouter } from './funding.router'
import { incentivesRouter } from './incentives.router'
import { proposalMediaRouter } from './media.router'
import { viewsRouter } from './views.router'

export const proposalsRouter = createEntityRouter(proposalServerSpec, (entity) => {
  return createTRPCRouter({
    // ── CRUD (5 single-row operations) ──────────────────────────────────
    // Generated by createCrudRouter. Create enrichment (kind derivation,
    // token gen, SOW snapshot) and duplicate config (field exclusion, status
    // reset) live on proposalServerSpec.hooks and .duplicate.
    //
    // crud.duplicate is overridden — the generic duplicateImpl only copies
    // the parent row, never `proposal_incentives` (a Wave-2 child table),
    // which would silently drop discounts/exclusive-offers on the copy. see
    // ../../../shared/entities/proposals/DOCS.md#duplicate-resets-and-redrives
    crud: createCrudRouter({
      spec: proposalServerSpec,
      schemas: { ...proposalSchemas, id: z.string().uuid() },
      authedProcedure: entity.authedProcedure,
      shareableProcedure: entity.shareableProcedure,
      handlers: {
        duplicate: duplicateProposalWithIncentives,
      },
    }),

    // ── Sub-routers (each a plain leaf in its own *.router.ts) ───────────
    business: businessRouter, // enriched reads + list
    incentives: incentivesRouter, // proposal_incentives replace-all (→ child entity S4)
    funding: fundingRouter, // narrow blob-scalar writes
    delivery: deliveryRouter, // send email, request-to-move-forward
    views: viewsRouter, // proposal_views: recordView (public) + getProposalViews
    contracts: contractsRouter, // envelope lifecycle + agreement context
    media: proposalMediaRouter, // plain leaf; child-scoped via proposalMediaProcedure (S5b)
  })
})
